static ComPtr<ID3DBlob> Compile(const char* name,const char* profile){ // [한국어 해설] 내장 raw string HLSL 바이트는 원본 그대로다. 오류 blob과 HRESULT를 숨기지 않는다.
 ComPtr<ID3DBlob> code,error;
